css:
:root {
  --bg-base: #0a0a0a;
  --bg-surface: #111111;
  --bg-card: #1f1f1f;
  --border: #2a2a2a;
  --text: #fafafa;
  --text-muted: #a1a1aa;
  --accent: #0ea5e9;
  --success: #22c55e;
  --danger: #ef4444;
  --warning: #f59e0b;

  /* Uma cor por fonte de receita — a mesma em pílula, gráfico e avatar. */
  --src-empresa: #0ea5e9;
  --src-impressionart: #8b5cf6;
  --src-moto: #f59e0b;
  --src-mos: #22c55e;
  --src-nata: #ec4899;

  --fonte: 'Manrope', sans-serif;
  --fonte-titulo: 'Sora', sans-serif;
  --fonte-mono: 'JetBrains Mono', monospace;
}

body { background: var(--bg-base); color: var(--text); font-family: var(--fonte); }

/* Número em tabela, card ou badge nunca "dança" ao atualizar. */
.bs-num { font-variant-numeric: tabular-nums; }

.bs-lista {
  /* As colunas moram numa custom property: cabeçalho e linha leem daqui, e a
     medida não se repete em dois lugares. */
  --colunas: 64px 1fr 120px 110px 120px;
  width: min(860px, 100%); padding: 20px;
}

/* --- celular --- */
.bs-lista-cards { display: flex; flex-direction: column; gap: 6px; }
.bs-lista-card {
  width: 100%; padding: 12px; text-align: left;
  border: 1px solid var(--border); border-radius: 10px; background: var(--bg-surface);
  font-family: var(--fonte);
}
.bs-lista-card-topo { display: flex; align-items: baseline; justify-content: space-between; gap: 10px; }
.bs-lista-card-titulo {
  min-width: 0; flex: 1; font-size: 13px; font-weight: 600; color: var(--text);
  overflow: hidden; text-overflow: ellipsis; white-space: nowrap;
}
.bs-lista-card-valor { flex-shrink: 0; font-family: var(--fonte-titulo); font-size: 13px; font-weight: 600; }
.bs-lista-card-meta { margin-top: 6px; font-size: 11px; color: var(--text-muted); }

/* --- desktop --- */
.bs-tabela { display: none; overflow: hidden; border: 1px solid var(--border); border-radius: 8px; font-size: 11px; }

@media (min-width: 768px) {
  .bs-lista-cards { display: none; }
  .bs-tabela { display: block; }
}

.bs-tabela-cabeca {
  display: grid; grid-template-columns: var(--colunas); gap: 8px;
  padding: 8px 10px; background: var(--bg-surface);
  font-size: 10px; text-transform: uppercase; letter-spacing: 0.05em; color: var(--text-muted);
}
.bs-tabela-linha {
  display: grid; grid-template-columns: var(--colunas); gap: 8px; align-items: center; width: 100%;
  padding: 8px 10px; border: none; border-top: 1px solid var(--border);
  font-family: var(--fonte); font-size: 11px; color: var(--text); text-align: left;
  background: transparent;
}
.bs-tabela-linha:hover { background: var(--bg-card); }

.bs-trunca { min-width: 0; overflow: hidden; text-overflow: ellipsis; white-space: nowrap; }
.bs-dir { text-align: right; }
.bs-pos { color: var(--success); }
.bs-neg { color: var(--danger); }

.bs-badge {
  padding: 3px 8px; border-radius: 6px;
  font-size: 10px; font-weight: 700; text-transform: uppercase; letter-spacing: 0.04em;
  color: var(--cor); background: color-mix(in srgb, var(--cor) 15%, transparent);
}
.bs-b-ok { --cor: var(--success); }
.bs-b-esp { --cor: var(--warning); }
